const WebSocket = require('ws');
const { verifySessionToken } = require('./auth');
const { canAccessTopic } = require('./permissions');

const wss = new WebSocket.Server({ port: 4444 });
const rooms = new Map();

wss.on('connection', async (ws, req) => {
  const user = await verifySessionToken(req);
  if (!user) {
    ws.close(4001, 'Unauthorized');
    return;
  }

  ws.on('message', async (message) => {
    const data = JSON.parse(message);
    if (data.type === 'subscribe') {
      const { topics } = data;
      const authorizedTopics = [];

      for (const topic of topics) {
        // Enforce authorization for each requested collaborative topic
        const hasAccess = await canAccessTopic(user.id, topic);
        if (hasAccess) {
          if (!rooms.has(topic)) {
            rooms.set(topic, new Set());
          }
          rooms.get(topic).add(ws);
          authorizedTopics.push(topic);
        }
      }

      ws.send(JSON.stringify({ type: 'subscribed', topics: authorizedTopics }));
    }
  });
});

module.exports = wss;
